package finance.client;
import finance.network.InsuranceResponsePacket;import java.util.concurrent.atomic.AtomicLong;
public final class InsuranceClientCache{public enum State{NOT_REQUESTED,LOADING,READY,SLOW}public record Entry(State state,long id,long at,InsuranceResponsePacket data){}private static final AtomicLong SEQ=new AtomicLong();private static Entry e=new Entry(State.NOT_REQUESTED,0,0,null);private InsuranceClientCache(){}public static long begin(){long id=SEQ.updateAndGet(v->v==Long.MAX_VALUE?1:v+1);e=new Entry(State.LOADING,id,System.currentTimeMillis(),null);return id;}public static void accept(InsuranceResponsePacket p){if(p.requestId()==e.id())e=new Entry(State.READY,p.requestId(),0,p);}public static Entry get(){return e.state()==State.LOADING&&System.currentTimeMillis()-e.at()>3000?new Entry(State.SLOW,e.id(),e.at(),e.data()):e;}public static void clear(){e=new Entry(State.NOT_REQUESTED,0,0,null);}}
